import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import html2canvas from 'html2canvas';

// const vazirmatnBase64 = "";

export function exportToExcel(data, fileName = 'data.xlsx') {
  try {
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
    XLSX.writeFile(wb, fileName);
  } catch (error) {
    console.error('خطا در خروجی اکسل:', error);
    alert('خطا در خروجی اکسل. لطفاً دوباره تلاش کنید.');
  }
}


export function exportToPDF(data, title = 'گزارش') {
  try {
    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.left = '-9999px';
    container.style.top = '0';
    container.style.width = '800px';
    container.style.background = 'white';
    container.style.padding = '20px';
    container.style.direction = 'rtl';
    container.style.fontFamily = 'Vazirmatn, sans-serif';
    container.style.zIndex = '-1000';
    
    const persianDate = new Date().toLocaleDateString('fa-IR');
    const headers = Object.keys(data[0] || {});
    
    let html = `
      <h2 style="text-align:center;font-size:20px;margin-bottom:5px;">${title}</h2>
      <p style="text-align:center;font-size:12px;color:#666;margin-bottom:15px;">تاریخ: ${persianDate}</p>
      <table style="width:100%;border-collapse:collapse;font-size:12px;text-align:center;">
        <thead>
          <tr style="background:#4f46e5;color:white;">
            ${headers.map(h => `<th style="padding:8px;border:1px solid #ddd;">${h}</th>`).join('')}
          </tr>
        </thead>
        <tbody>
          ${data.map(item => `
            <tr>
              ${headers.map(h => `<td style="padding:6px;border:1px solid #ddd;">${item[h] ?? ''}</td>`).join('')}
            </tr>
          `).join('')}
        </tbody>
      </table>
    `;
    
    container.innerHTML = html;
    document.body.appendChild(container);

    html2canvas(container, {
      scale: 2,
      useCORS: true,
      logging: false,
    }).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const doc = new jsPDF('p', 'mm', 'a4');
      const imgWidth = 210;
      const pageHeight = 295;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;
      let position = 0;

      doc.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      while (heightLeft > 0) {
        position = heightLeft - imgHeight;
        doc.addPage();
        doc.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      doc.save(`لیست_دروس_${persianDate}.pdf`);
      document.body.removeChild(container);
    }).catch((err) => {
      console.error('html2canvas error:', err);
      alert('خطا در ساخت تصویر جدول. لطفاً دوباره تلاش کنید.');
      document.body.removeChild(container);
    });

  } catch (error) {
    console.error('خطا در خروجی PDF:', error);
    alert('خطا در خروجی PDF. لطفاً دوباره تلاش کنید.');
  }
}

export function shareFavorites(favorites, totalUnits) {
  if (!favorites || favorites.length === 0) {
    alert('هیچ دوره‌ای برای اشتراک‌گذاری وجود ندارد.');
    return;
  }

  const list = favorites.map((item, index) => `${index + 1}. ${item}`).join('\n');

  const text = `📚 لیست دروس انتخابی من:\n\n${list}\n\n✅ مجموع واحدها: ${totalUnits}\n\n\nhttps://iaucourseexp.github.io/CoursesCodes/\nمرجع کد دروس آزاد شیراز`;

  if (navigator.share) {
    navigator.share({
      title: 'دوره‌های مورد علاقه',
      text: text,
      url: window.location.href
    }).catch(err => {
      if (err.name !== 'AbortError') {
        console.error('خطا در اشتراک‌گذاری:', err);
        fallbackShare(text);
      }
    });
  } else {
    fallbackShare(text);
  }
}

function fallbackShare(text) {
  navigator.clipboard?.writeText(text)
    .then(() => alert('لیست علاقه‌مندی‌ها در کلیپ‌بورد کپی شد!'))
    .catch(() => {
      const newWindow = window.open('', '_blank', 'width=400,height=300');
      if (newWindow) {
        newWindow.document.write(`<pre>${text}</pre>`);
        newWindow.document.title = 'دوره‌های مورد علاقه';
      } else {
        alert('لطفاً لیست را دستی کپی کنید:\n\n' + text);
      }
    });
}